import sys
import os
import json

def main():
    query = sys.argv[1] if len(sys.argv) > 1 else ""
    parts = query.split()
    shortcut = parts[0] if parts else ""
    # This is the text we will use to filter the results
    subfolder_filter = parts[1] if len(parts) > 1 else ""

    config_file = "/Users/csaborio/Library/CloudStorage/OneDrive-Personal/Application Settings/Alfred/Alfred.alfredpreferences/workflows/user.workflow.B5A1A856-928B-4CC0-AC6D-932FC355D213/fav_folders.txt"
    base_path = ""
    results = []
    direct_path = os.path.expanduser(query.strip())

    if os.path.isdir(direct_path):
        base_path = direct_path

    if not base_path:
        try:
            with open(config_file, 'r', encoding='utf-8') as f:
                for line in f:
                    if line.strip().startswith(shortcut + ' '):
                        line_parts = line.strip().split(' ', 1)
                        if len(line_parts) > 1:
                            base_path = line_parts[1]
                            break
        except Exception:
            pass

    if not base_path:
        results.append({"title": "Invalid Shortcut", "subtitle": f"Shortcut '{shortcut}' not found.", "valid": False})
        print(json.dumps({"items": results}))
        return

    try:
        # The search path should ONLY be the expanded base path
        search_path = os.path.expanduser(base_path)

        if os.path.isdir(search_path):
            for item in os.listdir(search_path):
                full_item_path = os.path.join(search_path, item)
                # THE FIX: Filter results here instead of changing the search path
                if os.path.isdir(full_item_path) and item.lower().startswith(subfolder_filter.lower()):
                    results.append({
                        "title": item,
                        "subtitle": full_item_path,
                        "arg": full_item_path,
                        "type": "file",
                        "uid": full_item_path
                    })
    except Exception as e:
        results.append({"title": "Error", "subtitle": str(e), "valid": False})

    # If nothing was found after filtering, show a "not found" message
    if not results and subfolder_filter:
         results.append({
            "title": f"No folders found matching '{subfolder_filter}'",
            "subtitle": f"In: {search_path}",
            "valid": False
        })

    print(json.dumps({"items": results}))

if __name__ == "__main__":
    main()
